{
  "story": "Follow a federal bill introduced in the House through committee review and votes in both chambers. Use Next to see when approval becomes law. This example keeps the text unchanged and ends with presidential signature. A veto instead requires a two-thirds vote in each chamber to override.",
  "aha": {
    "stateId": "law",
    "observation": "On this route, the bill becomes law after both chambers approve identical text and the President signs it."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "step-rail",
      "kind": "step-rail",
      "presentation": "Use the approved card shell, with story and instructions above the experiment. Show ordered steps with wrapped labels and the active step. Keep progress here. Brief parameter-control budget: zero; navigation comprises Previous, Next, and Reset.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "bill-path",
      "kind": "fixed-picture",
      "presentation": "Arrange named regions in a fixed left-to-right path using the tested part's layout. Highlight only the active region; mute inactive regions. Preserve readable labels at native width. No motion or fabricated time.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "active-explanation",
      "kind": "active-callout",
      "presentation": "Anchor beside the active region without covering labels. Identify its action and significance; leave numerical evidence in readouts.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "evidence",
      "kind": "value-readout",
      "presentation": "Place compact readouts below the picture, with Status last as a persistent status line. Matching approvals count House and Senate passage of unchanged text. Counts use exact integers, with no rounding. The fixed reference is both chambers.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "items": "variant.states",
      "label": "Bill stage",
      "presentation": "Use Previous and Next, retaining names when disabled at boundaries. Default to the first state; advance one integer index within the supplied states. Every state persists until learner action, including law. Provide accessible button names, visible focus, and keyboard activation. Reference captures show law."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all defaults. Provide an accessible name, visible focus, and keyboard activation."
    }
  ],
